import type { BusinessAction, BusinessMetrics } from '@ss/diagram-engine';
import type { CatalogEntry, DiagramLesson } from '@ss/lesson-engine';
import catalogJson from './catalog.json';

export type CourseLesson = DiagramLesson<BusinessMetrics, BusinessAction>;

/** Generated by `pnpm lessons`; validated in CI. */
export const catalog = catalogJson as CatalogEntry[];

const loaders = import.meta.glob<{ default: CourseLesson }>([
  './*.ts',
  '!./index.ts',
  '!./chapters.ts',
]);

export function loadLesson(slug: string): Promise<CourseLesson> | null {
  const load = loaders[`./${slug}.ts`];
  return load ? load().then((m) => m.default) : null;
}
